function winningPlayer(x, y) {
  // canWin(big, small): the player about to move wins with big 75-coins and small 10-coins left.
  // Every way of paying 115 is tried, so nothing about the moves is assumed.
  const memo = new Map();
  const canWin = (big, small) => {
    const key = big * 1000 + small;
    if (memo.has(key)) return memo.get(key);
    let win = false;
    for (let takeBig = 0; takeBig <= big && 75 * takeBig <= 115; takeBig++) {
      const takeSmall = (115 - 75 * takeBig) / 10;
      if (Number.isInteger(takeSmall) && takeSmall <= small && !canWin(big - takeBig, small - takeSmall)) win = true;
    }
    memo.set(key, win);
    return win;
  };
  return canWin(x, y) ? "Alice" : "Bob";
}

