function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') return [int(60, 100), int(60, 100)];
  const top = rand() < 0.5 ? 12 : 100;
  return [int(1, top), int(1, top)];
}
